from collections import defaultdict

class Solution:
    def validArrangement(self, pairs: list[list[int]]) -> list[list[int]]:
        adj = defaultdict(list)
        in_degree = defaultdict(int)
        out_degree = defaultdict(int)

        for u, v in pairs:
            adj[u].append(v)
            out_degree[u] += 1
            in_degree[v] += 1

        start = pairs[0][0]
        for node in out_degree:
            if out_degree[node] - in_degree[node] == 1:
                start = node
                break

        route = []
        stack = [start]
        while stack:
            while adj[stack[-1]]:
                stack.append(adj[stack[-1]].pop())
            route.append(stack.pop())

        route.reverse()
        return [[route[i], route[i + 1]] for i in range(len(route) - 1)]

#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<std::vector<int>> validArrangement(std::vector<std::vector<int>>& pairs) {
        std::unordered_map<int, std::vector<int>> adj;
        std::unordered_map<int, int> inDegree, outDegree;

        for (const auto& p : pairs) {
            adj[p[0]].push_back(p[1]);
            outDegree[p[0]]++;
            inDegree[p[1]]++;
        }

        int start = pairs[0][0];
        for (const auto& [node, out] : outDegree) {
            if (out - inDegree[node] == 1) {
                start = node;
                break;
            }
        }

        std::vector<int> route;
        std::vector<int> stack = {start};

        while (!stack.empty()) {
            int u = stack.back();
            if (!adj[u].empty()) {
                int v = adj[u].back();
                adj[u].pop_back();
                stack.push_back(v);
            } else {
                route.push_back(u);
                stack.pop_back();
            }
        }

        std::reverse(route.begin(), route.end());
        std::vector<std::vector<int>> ans;
        for (int i = 0; i < (int)route.size() - 1; ++i) {
            ans.push_back({route[i], route[i + 1]});
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[][] validArrangement(int[][] pairs) {
        Map<Integer, Deque<Integer>> adj = new HashMap<>();
        Map<Integer, Integer> inDegree = new HashMap<>();
        Map<Integer, Integer> outDegree = new HashMap<>();

        for (int[] p : pairs) {
            adj.computeIfAbsent(p[0], k -> new ArrayDeque<>()).push(p[1]);
            outDegree.put(p[0], outDegree.getOrDefault(p[0], 0) + 1);
            inDegree.put(p[1], inDegree.getOrDefault(p[1], 0) + 1);
        }

        int start = pairs[0][0];
        for (int node : outDegree.keySet()) {
            if (outDegree.get(node) - inDegree.getOrDefault(node, 0) == 1) {
                start = node;
                break;
            }
        }

        List<Integer> route = new ArrayList<>();
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);

        while (!stack.isEmpty()) {
            int u = stack.peek();
            Deque<Integer> neighbors = adj.get(u);
            if (neighbors != null && !neighbors.isEmpty()) {
                stack.push(neighbors.pop());
            } else {
                route.add(stack.pop());
            }
        }

        Collections.reverse(route);
        int[][] ans = new int[pairs.length][2];
        for (int i = 0; i < route.size() - 1; i++) {
            ans[i][0] = route.get(i);
            ans[i][1] = route.get(i + 1);
        }
        return ans;
    }
}

